/* Compile canonical names and compatibility aliases from one registry and CSS source. */
import { readFile, writeFile } from "node:fs/promises";
import { sharedSource } from "./lib/shared.mjs";
import { compile } from "./lib/naming.mjs";
const registry = JSON.parse(await readFile("naming/classes.json", "utf8"));
const check = process.argv.includes("--check");
for (const [file, { classes }] of Object.entries(registry.files)) {
  const css = compile(await sharedSource(file), file, registry);
  const output =
    "/* Generated by npm run build:naming. Edit source CSS and naming/classes.json. */\n" +
    css;
  const target = file.replace(/([^/]+)\.css$/, "public-$1.css");
  if (check) {
    if ((await readFile(target, "utf8")) !== output)
      throw Error("Stale named CSS: " + target);
  } else await writeFile(target, output);
}
console.log(
  `PASS naming build: ${Object.keys(registry.files).length} stylesheets, canonical selectors and original aliases`,
);
